import React, { useState } from 'react';
import PropTypes from 'prop-types';
import { Modal, ModalHeader, ModalBody, ModalFooter, Button } from 'reactstrap';

// core components
import Header from '../../components/header/header.jsx';
import HeaderBanner from '../../components/banner/banner.jsx';
import Footer from '../../components/footer/footer.jsx';

// sections for this page
import Buttons from './sections/buttons.jsx';
import ChatList from './sections/ChatList.jsx';

// 채팅방
const ChatPage = ({ toggleChat }) => {
    return (
        <div className="chat-page">
            <ChatList toggleChat={toggleChat} />
        </div>
    );
};

const Components = () => {
    const [showChatPage, setShowChatPage] = useState(false);
    const [currentChat, setCurrentChat] = useState(null);

    const toggleChatPage = () => {
        console.log('Chat page visibility:', !showChatPage); // 토글 상태 로그
        setShowChatPage(!showChatPage);
    };

    const toggleChat = (chatId, otherUserId) => {
        setCurrentChat({ chatId, otherUserId });
        setShowChatPage(true);
    };

    return (
        <div id="main-wrapper">
            <Header />
            <div className="page-wrapper">
                <div className="container-fluid">
                    <HeaderBanner />
                    <Buttons />
                    <button
                        className="fixed-chat-button"
                        onClick={toggleChatPage}
                        style={{ position: 'absolute', top: '10px', right: '10px', zIndex: 1050 }}
                    >
                        채팅창 이동
                    </button>
                    <Modal isOpen={showChatPage} toggle={toggleChatPage} centered>
                        <ModalHeader toggle={toggleChatPage}>
                            채팅방
                            <button
                                className="fixed-chat-button"
                                onClick={toggleChatPage}
                                style={{ position: 'absolute', top: '10px', right: '10px' }}
                            >
                                채팅창 이동
                            </button>
                        </ModalHeader>
                        <ModalBody>
                            <ChatPage toggleChat={toggleChat} />
                        </ModalBody>
                        <ModalFooter>
                            <Button color="secondary" onClick={toggleChatPage}>
                                닫기
                            </Button>
                        </ModalFooter>
                    </Modal>
                </div>
            </div>
            <Footer />
        </div>
    );
};

Components.propTypes = {
    classes: PropTypes.object,
};

export default Components;
